/* The Spire – Strata · Lines in the Dirt (deutscher Buchtext aus quellen/spire/de/str/t04i-lines-in-the-dirt.md, erzeugt mit plan/spire/build_erw.py) */
(window.SP_ERW = window.SP_ERW || {})["str/lines-in-the-dirt"] = {"id":"lines-in-the-dirt","buch":"str","t":"Lines in the Dirt","p":183,"pe":198,"b":["*Von Pauline Chan*","**Inhaltswarnungen:** Alkoholismus, PTBS, sexuelle Belästigung.",{"t":"h","x":"Einleitung","p":183,"lvl":2,"id":"einleitung"},"*Hinweis: Dieses Szenario kann mehrere heikle Themen berühren, darunter PTBS, Alkoholismus, sexuelle Belästigung und Tod. Du kannst Elemente nach Bedarf verändern oder entfernen, ohne die Geschichte zu beeinträchtigen; im Zweifel nutze die X-Card. Vor allem aber: Sei bitte freundlich zu dir selbst und zu deinen Spielenden.*","Unten im Dreck und Morast von Derelictus wirkt das Alltagsleben auf Außenstehende wie ein Albtraum. Der Rat hoch oben im Spire hat diesen Distrikt längst abgeschrieben. Die Menschen hier haben jedoch enge Gemeinschaften gebildet und gedeihen, frei vom Blick der Aelfir (aber immer in der Erwartung, dass ihre abwesenden Oberherren sich eines Tages doch an sie erinnern).","Eines Tages wachen die Bewohner der Boundary Road 228 auf und finden an ihren Türen Räumungsbescheide ihres neuen Aelfir-Vermieters. Das Amt für Wohnungswesen hat das Gebäude für unbewohnbar erklärt: Die Bewohner haben eine Woche Zeit auszuziehen, bevor die Wachen das Haus mit Gewalt räumen. Bleibt das unangefochten, landen die meisten auf der Straße, und die eng verbundene Gemeinschaft zerfällt.","Um dieser Ungerechtigkeit zu begegnen, hat das Ministerium die Zelle der Spielerfiguren gerufen, die allesamt in dem Gebäude wohnen. Die Spielerfiguren sollen ihr Zuhause retten, mit allen nötigen Mitteln. Ihre Nachbarn sind ebenfalls wütend und könnten helfen – doch wenn jemand herausfindet, dass sie Ministeriumsagenten sind, könnten sie stattdessen zum Faustpfand werden.",{"t":"h","x":"Was Geht Hier Wirklich vor Sich?","p":183,"lvl":2,"id":"was-geht-hier-wirklich-vor-sich"},"Für Außenstehende ist dieses Mietshaus wie alle anderen in Derelictus – heruntergekommen, überbelegt und unauffällig –, aber es liegt nah genug an Red Row, um erreichbar zu sein, und ist billiger als alles dort. Die Menschen in Derelictus wissen jedoch, dass die Zimmer deshalb weniger kosten, weil sich die von Kannibalen beherrschte Region Grist ausdehnt und in den letzten Jahren immer näher rückt, je mehr Menschen zu Ghulen werden.","Dennoch ist dieses Gebäude seinen Bewohnern etwas Besonderes, denn es ist zugleich Heim und Gemeinschaft: eine, die aus Not, Zusammenarbeit und Vertrautheit entstanden ist, aus geteilten Bädern, geteilten Küchen und dünnen Wänden. Nur wenige wissen, dass eine kürzliche Begutachtung ungewöhnlich hohe Mengen okkulter Energie ergab, die durch die rissigen Fundamente ins Gebäude sickert.","Der Prüfer, der das entdeckte, konnte das Ausmaß des Schadens nicht bestimmen, weil Marguerite, die Midwife, die ihr Versteck im Keller hat, Außenstehenden den Zutritt gewaltsam verwehrt hat, um die ihr anvertrauten Eier zu schützen. Der Bericht des Prüfers, archiviert im Amt für Wohnungswesen, hält fest, dass die Menge an okkulter Energie die Standfestigkeit des Gebäudes wahrscheinlich beeinträchtigt hat. Wird nichts repariert, wird es aller Voraussicht nach einstürzen.","Unterdessen hat Faizel Schnee-fällt-auf-Glut [[Snow-Falling-on-Embers]] seine wohlhabenden Standesgenossen schockiert, als er das Mietshaus kaufte. Er ist einer von nur einer Handvoll Aelfir, die je im Distrikt Grundbesitz hatten. Um seine politischen Ambitionen voranzutreiben, plant er, das Gebäude in ein philanthropisches Projekt zu verwandeln, das darauf abzielt, die Drow zu „erheben“. Angeregt wurde das durch Gespräche mit Amondieu, der kürzlich seine Dienstzeit bei Faizel beendet hat (Faizel hat Amondieu davon nichts gesagt).","Um seine Vision umzusetzen, hat Faizel Harmonious Properties angeheuert, ein neues Immobilienunternehmen, das die Konkurrenz unterboten hat, um den Zuschlag zu bekommen. Sie sollen das Gebäude gemäß Faizels uneinheitlich konkreten Vorgaben und seinem ehrgeizigen Zeitplan abreißen, neu bauen und verwalten. Ohne dass Faizel es weiß, ist Harmonious Properties in Wahrheit eine Tarnfirma des Herold-Konzerns.","Ihre Pläne sind zweigeteilt: Erstens wollen sie ein verstecktes Labor errichten, um ohne Einmischung oder Aufsicht zu forschen. Zweitens wollen sie, nachdem sie subventionierten Wohnraum und Gratisbrot angeboten haben, ohne Einwilligung der Bewohner Experimente an ihnen durchführen – von Tests mit Nahrung, die mit verschiedenen Stämmen der Vyskant-Krankheit infiziert ist, bis hin zur Erkundung alternativer Übertragungswege in einer kontrollierten Umgebung.",{"t":"h","x":"Aufbau des Abenteuers","p":184,"lvl":2,"id":"aufbau-des-abenteuers"},"Spielleitung: Die Eröffnungsszene sollte den Räumungsbescheid, das Gebäude und die Menschen, die dort leben, einführen, einschließlich der Spielerfiguren. Die Szene „Der Räumungsbescheid“ bietet ein Beispielgerüst, um das oben Genannte vorzustellen; im Mittelpunkt stehen die Nachbarn der Figuren, die nützliche Ressourcen haben und die im Spiel befindlichen Konflikte offenlegen können.","Am Ende der Szene sollten die Spielenden wissen, welchen Spuren sie nachgehen und welche Optionen sie erwägen wollen. Von da an haben die Figuren eine Spielwoche Zeit, ihren Plan zu machen und dann danach zu handeln. Die Handlungsstränge sind nach Fraktionen geordnet und bieten mögliche Auslöseszenen, zugehörige NSC, Informationsblöcke und Wege, sie in Erfahrung zu bringen, während der Abschnitt „NSC“ die übrigen Nachbarn abdeckt. Das Zeitlimit ist ein Werkzeug, um Dringlichkeit zu vermitteln und dramatische Spannung zu erzeugen, wenn du sie willst; du musst nicht jede Minute abrechnen.","Dieses Abenteuer geht von drei Wahrheiten über die Spielerfiguren aus: Erstens wohnen sie alle als Mitbewohner im Gebäude; zweitens können sie es sich wie die meisten Bewohner nicht leisten, kurzfristig umzuziehen; und drittens sind sie alle Mitglieder einer unterfinanzierten Ministeriumszelle. Außerdem sollte jede Figur eine persönliche Verbindung zur Geschichte, Bindungen zu den anderen und eine Bindung zu einem ihrer Nachbarn haben. Diese können vor dem Spiel zugewiesen werden, je nachdem, welche Art von Figuren die Spielenden erschaffen.","Trotz der Vertrautheit, die das Leben auf so engem Raum mit sich bringt, ist es den Figuren bisher gelungen, ihre Zelle geheim zu halten (oder zumindest hat sie noch niemand angezeigt). Aber die Figuren haben noch nie Ministeriumsarbeit so nah an Menschen geleistet, die sie schon kennen.","Einerseits gehören sie einer eng verbundenen Gemeinschaft an, und ihre NSC-Nachbarn haben kein Verlangen, mehr Ärger heraufzubeschwören, als sie ohnehin schon haben. Andererseits besagt das Gesetz von Spire unmissverständlich, dass die Beihilfe zu Ministeriumsmitgliedern ein Todesurteil ist. Schlimmer noch: Die Belohnung für ihre Anzeige ist mehr Geld, als die meisten in Derelictus je gesehen haben.","Im Laufe der Woche werden alle nur noch verzweifelter darum bemüht sein, sich selbst oder ihre Gemeinschaft zu retten. Die Gefahr, dass NSC die Spielerzelle verraten, sollte während der gesamten Kampagne gegenwärtig sein und gegen die Handlungen der Figuren abgewogen werden.","Mit kleinen Anpassungen kannst du dieses Abenteuer in die Rekrutierungsgeschichte der Figuren für das Ministerium umwandeln. In diesem Fall erhalten die Figuren zu Beginn des Abenteuers keine Nachricht von einem Magister, laufen aber dennoch Gefahr, als Ministeriumsmitglieder gemeldet zu werden, und müssen dieselben Konsequenzen tragen, da ihre Handlungen vermutlich typischem Ministeriumsverhalten ähneln. Wann die Rekrutierungsansprache stattfindet, liegt bei dir, aber im Allgemeinen wartet ein Magister auf Ergebnisse (oder einen Punkt ohne Rückkehr), bevor er seine eigene Tarnung riskiert, um ein Gespräch zu führen.",{"t":"h","x":"Fallout der Nachbarschaft","p":184,"lvl":2,"id":"fallout-der-nachbarschaft"},{"t":"h","x":"Mittel","p":184,"lvl":3,"id":"mittel"},{"t":"hw","x":[{"k":"AUSVERKAUFT","x":"[Schatten] Ein feindseliger oder verzweifelter NSC gibt den Wachen einen anonymen Hinweis, dass eine oder mehrere Spielerfiguren Ministeriumsmitglieder sein könnten. Ein freundlicher NSC warnt sie, weil er fürchtet, die Wachen würden jeden ins Visier nehmen, der mit den Figuren zu tun hat – ihn selbst eingeschlossen.","p":184},{"k":"KOLLATERALSCHADEN","x":"[Schatten] Ein NSC erzählt den Wachen, das Ministerium sei an den Vorgängen beteiligt gewesen – doch das Ministerium kontrolliert den Wachposten, den er aufsucht. Sie informieren dich über das Handeln des NSC per toter Briefkasten und ordnen an, diese potenzielle Gefahr zum Schweigen zu bringen.","p":184}]},"NACHBARN **(MEHR INFORMATIONEN IM ABSCHNITT NSC)**","**Nachbar**","**Verbindung/Wissen**","Marguerite, die Midwife","Midwives, Nachbarn, das Gebäude, Heilung","(Handlungsstrang Mietshaus)","Guensy, der Zahnarzt","Bürokratie, Verbrauchsgüter, Heilung","Roseline und Nadia, die Tanten*","Derelictus, Nachbarn, Gerüchte, gefälschte Waren","Amondieu Loukes","Adlige, Faizel","Mama Loukes","Grist, nützliche gebastelte Gegenstände","Zette und Selavi, Malak-Dealerinnen","Derelictus, örtliche Banden, Drogen","*„Tante“ ist eine freundliche Anrede für eine erwachsene Frau, ob verwandt oder nicht. Innerhalb ihrer Gemeinschaft stürzen sie sich wie Glucken auf einen, um Wangen zu kneifen, sich nach Gesundheit und Zuhause zu erkundigen, über unschöne persönliche Angewohnheiten zu schimpfen und Essen anzubieten, wenn man hungrig aussieht (und man sieht immer hungrig aus).",{"t":"h","x":"Die Geschichte","p":185,"lvl":2,"id":"die-geschichte"},{"t":"h","x":"Eröffnungsszene: der Räumungsbescheid","p":185,"lvl":3,"id":"eroeffnungsszene-der-raeumungsbescheid"},"Die Spielerfiguren entdecken einen Räumungsbescheid, der an jeder Tür angebracht wurde, als sie gerade hinausgehen, nach lauten Stimmen im Flur sehen oder nach einer langen Nacht heimkehren. Die Nachricht überrascht alle, auch die Spielerzelle. Ihre Nachbarinnen von nebenan, Roseline und Nadia, stehen im Flur, empört und laut genug, um Tote zu wecken.","Die Figuren haben viel Spielraum dabei, wie sie Informationen sammeln. Wenn sie nicht wissen, was sie tun sollen, können Roseline und Nadia zum Tratschen vorbeikommen und einen Überblick über die Lage geben, um die Spielenden auf den Weg zu bringen.","Der Bescheid besagt, dass das Amt für Wohnungswesen das Gebäude für unbewohnbar erklärt hat, weshalb der neue Eigentümer – ein gewisser Faizel Schnee-fällt-auf-Glut – den Bewohnern eine Woche gibt, auszuziehen, oder sie müssen mit Verhaftung rechnen. Die Bewohner dürfen die Vertreter von Harmonious Properties nicht behindern, denen freier Zutritt zum Gebäude gewährt wurde, um den Abriss zu planen und vorzubereiten. Auf der Rückseite weist der gewöhnlich abwesende Magister der Figuren die Spielerzelle an, „etwas Initiative zu zeigen“.","Selbst Roseline und Nadia, die von allem hören, hat die Räumung kalt erwischt. Kein anderes Gebäude hat einen Bescheid erhalten. Der neue Eigentümer trägt einen Aelfir-Nachnamen, aber die Hochelfen nehmen kaum zur Kenntnis, dass Derelictus überhaupt existiert. Amondieu weiß vielleicht mehr, da er seine Dienstzeit bei einem Masked-Lord abgeleistet hat. Seltsam ist auch, dass jemand ein Gebäude auf Grists sich ausbreitendem Weg renovieren will, aber niemand weiß mehr über das Gebäude als Marguerite, die Midwife im Keller.","Wenn die Figuren nach anderen Themen fragen, siehe die Tabelle der Nachbarn, um zu sehen, wen Roseline und Nadia empfehlen würden (oder was sie selbst beantworten können).",{"t":"h","x":"Handlungsstränge","p":185,"lvl":2,"id":"handlungsstraenge"},"Die Handlungsstränge unten können in beliebiger Reihenfolge angegangen werden, wobei je nach Entscheidungen der Spielenden nicht alle nötig sein müssen. Jeder Strang hat ein paar mögliche Auslöseszenen, um die Spielerfiguren einzubinden: Nutze, was zur Situation passt, und ignoriere den Rest ruhig. Die Nachbarn sollten Spuren liefern können, falls die Spielerfiguren keine in ihren Hintergründen haben. Versuche, proaktiv auf die Spielenden zuzugehen, mit Blick auf die Lösung des Problems.",{"t":"h","x":"Handlungsstrang: das Mietshaus","p":185,"lvl":3,"id":"handlungsstrang-das-mietshaus"},"Das Gebäude war nie etwas Besonderes – dachten zumindest alle. Klar, es ist wahrscheinlich eine Gesundheitsgefahr und verstößt gegen ein halbes Dutzend Bauvorschriften, aber das tut jedes andere Gebäude in Derelictus auch. Oder?",{"t":"h","x":"NSC: Nezha Dey","p":186,"lvl":4,"id":"nsc-nezha-dey"},"**Warum ist die Person beteiligt?**","Nezha ist nicht bloß die Managerin von Harmonious Properties, die das Projekt leitet: Nezha ist ein Visionär. Wie alle in der Firma ist Nezha außerdem mit der Vyskant-Krankheit infiziert.","**Was hebt sie von den anderen Angestellten ab?**","Nezhas Perfektionismus reicht weit über das hinaus, was irgendjemand verlangt. Trotz langer Gespräche über Budgets und Gewinnmargen will Nezha ein neues Gebäude errichten, das nicht bloß ausreichend, sondern beispielhaft ist. Dass dieses Gebäude in Derelictus steht, dass solch hochfliegende Ambitionen Verzögerungen und Mehrkosten verursachen werden und dass Nezha die tatsächlichen Bedürfnisse der Bewohner weder kennt noch sich darum schert, spielt keine Rolle.","**Was wünscht sich die Person?**","Vor der Infektion war Nezha ein aufstrebender Künstler. Der Drang zu erschaffen ist nie verschwunden, auch wenn sich der ästhetische Geschmack vom Glorreichen zum Grotesken verschoben hat. Nun leitet Nezha das Projekt nicht nur, um die Expansionspläne des Herold-Konzerns zu erfüllen, sondern auch, um ein Meisterwerk zu schaffen, inspiriert von den glitzernden Türmen aus Knochen und Sehnen, die sich durch Nezhas Träume winden. Niemand kennt diese Pläne bisher, und Nezha hat nicht vor, sie preiszugeben, ehe es zu spät ist, den Kurs umzukehren.","**Was verachtet die Person?**","Nezha verachtet Menschen ohne Vision oder Ehrgeiz. Für Politik, Budgets oder die Kleinigkeiten des Alltags hat Nezha wenig Geduld, einschließlich Mahlzeiten und dem Schicksal ungeschlüpfter Drow-Kinder.",{"t":"h","x":"NSC: Marguerite, die Midwife","p":186,"lvl":4,"id":"nsc-marguerite-die-midwife"},"**Warum ist sie beteiligt?**","Marguerite hat ihr Versteck vor Jahrzehnten im Keller eingerichtet. Sie ist eine Säule der Gemeinschaft und dient als Heilerin, Leihmutter, Therapeutin und Beschützerin sowie als örtliche Midwife. Sie nimmt alle ihre Verantwortlichkeiten ernst. Vor einem Monat erwischte sie einen Gebäudeprüfer des Amts für Wohnungswesen dabei, wie er in den Keller wollte, und hält seither Ausschau nach Ärger.","**Was hebt sie von den anderen Bewohnern ab?**","Während die Tanten vielleicht den neuesten Klatsch aus Derelictus kennen, ist Marguerites Informationsnetz eine Macht, mit der man rechnen muss. Ihre Spinnen sind überall im Gebäude, daneben hat sie winzige, weit verstreute Späher anderswo in der Stadt, um auf dem Laufenden zu bleiben. Sie hat ihr Versteck kaum noch verlassen, seit sie mehr Spinnenmerkmale angenommen hat.","**Was wünscht sie sich?**","Marguerite will ihr Gelege, ihre Leute und ihr Zuhause schützen. Da sie spürt, dass ein Konflikt am Horizont steht, nutzt sie einen Teil der okkulten Energie, die durch die Fundamente sickert, um ihre Schutzvorkehrungen zu verstärken. Sie sucht außerdem Verbündete und hat reichlich Verbindungen, Gefallen und ungebetene Ratschläge zu bieten, im Austausch für Hilfe.","**Was verachtet sie?**","Außenstehende, Bedrohungen für ihr Gelege und ihre Gemeinschaft. Wenn sie provoziert wird, wird sie nicht zögern, alles und jeden einzusetzen, was ihr zur Verfügung steht, um sie zu verteidigen.",{"t":"h","x":"Fallout","p":186,"lvl":4,"id":"fallout"},{"t":"hw","x":[{"k":"VERSPONNEN","x":"[Leicht, Ruf/Schatten] Nachdem die Figuren Marguerites Argwohn geweckt haben, finden sie ein Spinnennetz vor ihrer Tür, das mit dem Wort „ERKLÄRT“ in der Mitte gewebt ist. Keine Spinne ist zu sehen. Das ist nie ein gutes Zeichen. Währenddessen machen eure Nachbarn einen großen Bogen um euch.","p":186}]},{"t":"h","x":"Vorgeschlagene Szenen","p":186,"lvl":4,"id":"vorgeschlagene-szenen"},{"t":"szenen","x":["Die Figuren gehen nach unten, um mit Marguerite zu sprechen und Antworten über das Gebäude zu suchen. Sie finden sie mitten in einem Streit mit einem nervös wirkenden Menschen, der sich Zutritt zum Keller verschaffen will. Der Mensch ist Nezha Dey, die Projektmanagerin von Harmonious Properties, die die Spielenden anfleht, Marguerite zur Vernunft zu bringen. Die Midwife weigert sich, irgendeinen Fremden an die Eier heranzulassen, die den Boden bedecken.","Die Figuren stehen im Treppenhaus, als sie Geräusche eines ernsten Kampfes von unten hören. Im Keller finden sie drei Fremde von Harmonious Properties: zwei bereits tot und die letzte, Nezha Dey, in einem Netz gefangen. Marguerite hockt an der Wand, hält aber inne, als die Figuren eintreten. Nezha glaubt, die Figuren seien gekommen, um die Sache zu Ende zu bringen, und droht, die Wachen auf alle zu hetzen. In Wahrheit kamen die beiden toten Angestellten von Harmonious Properties, um Marguerite zu ermorden, als sie erkannten, dass sie durch ihre Spinnen vom geplanten geheimen Labor wusste. Nun gibt es zwei Leichen zu beseitigen, eine verängstigte Managerin und eine Midwife, die noch immer in der Defensive ist. Marguerite wird dankbar sein, wenn die Figuren beim Aufräumen helfen. Es wird nicht leicht, Nezha zum Schweigen zu bewegen, aber als Bauleiterin würde man es bemerken, wenn sie verschwindet."]},{"t":"h","x":"Die Figuren Ermitteln Harmonious Properties","p":187,"lvl":4,"id":"die-figuren-ermitteln-harmonious-properties"},{"t":"hw","x":[{"k":"• Ihre wohltätige Geste ist eine Farce","x":"Harmonious Properties gewann die Ausschreibung für den Bau, obwohl die Firma keine Projekte vorzuweisen hat, indem sie die Konkurrenz unterbot und anbot, den Bewohnern subventionierten Wohnraum und Gratisbrot zu bieten. Faizel war von dem Plan so begeistert, dass er sie auf der Stelle unter Vertrag nahm. Es ist zu schön, um wahr zu sein: Im Gegenzug für diese Vergünstigungen plant die Firma, an ihren ahnungslosen Bewohnern verschiedene Infektionswege der Vyskant-Krankheit zu testen. Die Infektionsrate ist derzeit niedrig, aber sie glauben, dass dieses Projekt den Durchbruch bringen kann, den sie brauchen.","p":187},{"k":"• Harmonious Properties wird vom Herold-Konzern gestützt","x":"Auf dem Papier ist Harmonious Properties ein unabhängiges Unternehmen, tatsächlich aber wird es vom Herold-Konzern finanziert und geführt. Mehr noch: Der Herold-Konzern ist selbst eine Fassade: Er ist bekannt dafür, Gratisbrot zu verteilen, weniger dafür, dass er letztlich die Bevölkerung von Spire über sein Brotprogramm mit der Vyskant-Krankheit anstecken will.","p":187}]},{"t":"h","x":"Die Figuren Ermitteln der Keller","p":187,"lvl":4,"id":"die-figuren-ermitteln-der-keller"},{"t":"hw","x":[{"k":"• Marguerites Gelege kann nicht bewegt werden","x":"Marguerites Kellerversteck ist voller Netze und Drow-Eier von Eltern aus ihrem gesamten Revier; die neuesten Eier sind erst wenige Tage alt. Einmal abgelegt, können die Eier nicht bewegt werden und müssen von der Midwife umsorgt werden, bis sie schlüpfen – sonst überleben sie nicht.","p":187},{"k":"• Okkulte Energie sickert durch Risse im Fundament des Gebäudes","x":"Sowohl Marguerite als auch Nezha kennen das Netz aus Rissen, das den Kellerboden durchzieht, groß genug, um besorgniserregend zu sein, und tief genug, damit okkulte Energie aus dem Vermissian eindringen kann. Das Fundament ist beeinträchtigt und braucht wahrscheinlich teure Reparaturen. Sie zu beheben würde das Gebäude stabilisieren und diese Energiequelle versiegeln, aber sowohl Marguerite als auch der Herold-Konzern sind daran interessiert, diese Macht für ihre Ziele zu nutzen.","p":187}]},{"t":"h","x":"Handlungsstrang: Amt für Wohnungswesen","p":187,"lvl":3,"id":"handlungsstrang-amt-fuer-wohnungswesen"},"Das Amt für Wohnungswesen stellt täglich überall in Spire Räumungsbescheide aus, aber in Derelictus ist es selten, einen zu erhalten, weil jedes einzelne Gebäude gegen die Bauordnung verstößt. Die Vorschriften des Amts dienen im Allgemeinen dazu, den Wachen einen Vorwand für eine Razzia zu liefern oder (selten) ein Gebäude zu entfernen, das irgendwie die Menschen hoch oben im Spire gefährdet. Keine der beiden Möglichkeiten scheint zu dieser Lage zu passen.",{"t":"h","x":"NSC: Unter-Unterstaatssekretärin Adolise Vern","p":187,"lvl":4,"id":"nsc-unter-unterstaatssekretaerin-adolise-vern"},"**Warum ist sie beteiligt?**","Zu Adolises vielen Zuständigkeiten gehört die Befugnis, Räumungen zu erlassen oder aufzuheben. Sie hat den Bescheid abgezeichnet, der am Gebäude der Spielerfiguren angebracht wurde. Schade, dass sie sonst eine Prinzipienreiterin ist.","**Was hebt sie von den anderen Verwaltungsbeamten ab?**","Vor zwei Jahrzehnten gehörte sie zu den Besten und Klügsten ihrer Generation: eine seltene Drow mit der Zähigkeit und dem Ehrgeiz, die Ränge bis in eine Machtposition hinaufzuklettern. Heute ist sie eine abgehalfterte Alkoholikerin, deren Karriere stagniert, während jüngere Aelfir an ihr vorbeiziehen; tatsächlich war ihr jetziger Vorgesetzter einst einer ihrer direkten Untergebenen. Dennoch bleibt sie und erfüllt ihre Pflichten so gut sie kann, zum Wohl der Allgemeinheit.","**Was wünscht sie sich?**","Steife Drinks, eine Beförderung und etwas Respekt. Jahre kleiner und großer Demütigungen haben sie verbittert und zum Trinken getrieben. Bisher hat sie dieses Problem vor ihren Kollegen verbergen können. Sie weiß, dass die Leitung sie ersetzen wird, wenn sie aufhört, nützlich zu sein. (Leider hat sie das nur noch mehr trinken lassen.)","**Was verachtet sie?**","Menschen, die das System missbrauchen oder brechen, vor allem zum eigenen Vorteil. Sie räumt zwar ein, dass die Gesetze des Landes weder gerecht noch gerecht angewendet sind, besteht aber darauf, dass sie dennoch befolgt werden müssen, weil sie die Armen theoretisch vor den räuberischen Machenschaften der Reichen schützen könnten – wenn ein prinzipientreuerer Verwalter die Kontrolle hätte.",{"t":"h","x":"Vorgeschlagene Szenen","p":188,"lvl":4,"id":"vorgeschlagene-szenen-2"},{"t":"szenen","x":["Der Adresse auf dem Räumungsbescheid folgend, reisen die Figuren tagsüber hinauf in den oberen Spire zur überfüllten Eingangshalle des Amts für Wohnungswesen. Ein wütender Schreiber sagt ihnen, sie sollten einen Termin vereinbaren, aber der nächste freie ist Monate entfernt, und für eine Kopie der Gebäudeunterlagen braucht man eine Notiz des Vermieters. Neben dem Schreiber führt eine unverschlossene Tür zu den Büros, und die Figuren können versuchen, sich hineinzuschleichen. Drinnen geht Adolise davon aus, dass sie eine Erlaubnis haben, solange die Figuren nichts Gegenteiliges durchblicken lassen.","Die Figuren beschließen, nachts ins Amt für Wohnungswesen einzubrechen, um Papiere zu stehlen oder zu fälschen. Adolises Aelfir-Schreiber Pelham Flamme-in-Blüten [[Blaze-in-Blossoms]] ist jedoch bereits eingebrochen, in der Absicht, sie in Misskredit zu bringen und ihre Stelle zu übernehmen. Er hat erheblich weniger Skrupel als seine Vorgesetzte und bietet den Spielenden an, ihnen zu helfen, das zu finden, was sie suchen, im Gegenzug für ihr Schweigen.","Adolise ist weit jenseits von betrunken, als die Spielenden sie nach Feierabend in der Bar finden. Sie hat Mühe, den Kopf oben zu halten, während sie ihrer Flasche etwas vorschimpft, was erklären dürfte, warum die Plätze um sie herum leer sind. Die Figuren können Fragen stellen, ihr eine Falle stellen oder Mitleid haben und sie nach Hause begleiten, mit Blick auf Zusammenarbeit oder Erpressung (in diesem Fall könnten sie sie sogar als Bindung für ein fortlaufendes Spiel gewinnen)."]},{"t":"h","x":"Die Figuren Ermitteln der Räumungsbescheid","p":188,"lvl":4,"id":"die-figuren-ermitteln-der-raeumungsbescheid"},{"t":"hw","x":[{"k":"• Das Gebäude gehört vollständig Faizel Schnee-fällt-auf-Glut","x":"Das ist nicht überraschend, bestätigt aber, dass Faizel allein befugt ist, dieses Projekt zu starten oder zu stoppen, und auch, dass er die Räumungen genehmigt hat. Überraschend ist, wie wenig er für das Gebäude bezahlt hat, selbst nach den Maßstäben von Derelictus. Sollte Faizel es äußerst lästig finden, das Gebäude zu behalten, könnten die Figuren sogar versuchen, es ihm abzukaufen – wobei es schwierig wird, die nötigen Mittel aufzutreiben und Faizel zu überzeugen, sein Lieblingsprojekt aufzugeben. Es wären drei bis vier Herausforderungen mit Schwierigkeit 2, die je nachdem, wie die Figuren an die Situation herangehen und Faizel ihren Fall darlegen, auf Schwierigkeit 1 herabgestuft werden können.","p":188}]},"Stimmt Faizel zu und haben die Figuren ausreichende Mittel beschafft, betragen die Kosten des Gebäudes W8 Silber oder W6 mit einer zusätzlichen Probe auf Überzeugen+Handel/Hohe Gesellschaft für gemeinsames Eigentum.",{"t":"hw","x":[{"k":"• Das Gebäude ist eine echte Sicherheitsgefahr","x":"Laut Prüfbericht hat das Gebäude eine lange Mängelliste, die es für Bewohner untauglich macht. Die meisten sind typisch für Gebäude in Derelictus, aber zwei sind besorgniserregender: Die Fundamente sind beschädigt, und okkulte Energie sickert aus den Vermissian-Tunneln darunter herein. Der Prüfer konnte nicht überprüfen, wie schwer der Schaden war, weil Marguerite den Zutritt verweigerte, aber es sind schlechte Nachrichten, wenn Unwirklichkeit von unten hereinsickert. Die Prüfung fand vor Faizels Kauf statt, also kennt er das Problem – ebenso wie Harmonious Properties.","p":188},{"k":"• Das Amt wurde bestochen, um das Räumungsverfahren zu beschleunigen","x":"Der Bescheid ist rechtmäßig, aber Faizel ging über Adolises Kopf hinweg, um die Genehmigung zu sichern. Das wurmt sie weiterhin, weil es technisch illegal ist, aber wie die meisten Gesetze in Spire gilt das nicht für wohlhabende Adlige. Allerdings gibt es ein (absichtlich) obskures Einspruchsverfahren. Die Figuren können Adolise (oder Pelham, falls sie stattdessen ins Büro eingebrochen sind) überzeugen, Formulare und Anweisungen herauszugeben, oder sie können ermitteln, um die Formulare selbst zu finden.","p":188}]},{"t":"gegner","id":"erw-str-gebaeudewachen"},{"t":"h","x":"Weitere NICHTSPIELERFIGUREN (NSC)","p":188,"lvl":2,"id":"weitere-nichtspielerfiguren-nsc"},{"t":"h","x":"Der Unlizenzierte Zahnarzt","p":188,"lvl":3,"id":"der-unlizenzierte-zahnarzt"},{"t":"h","x":"Guensy Devare","p":188,"lvl":4,"id":"guensy-devare"},"**Was bietet die Person der Gemeinschaft?**","Guensy fiel vor einigen Jahren in Ungnade und strandete in Derelictus. Während Marguerite Beratung und schwere Verletzungen übernimmt, bietet Guensy einfache medizinische Dienste und einen verblüffend umfassenden Vorrat an medizinischem Bedarf, im Tausch gegen Naturalien und das Schweigen der Patienten. Die Praxis ist weiterhin geöffnet.","**Was hebt die Person vom Rest der Gemeinschaft ab?**","Anders als die meisten Menschen im Distrikt lebte Guensy die meiste Zeit des Lebens hoch oben im Spire, was ihm eine Außenperspektive und ein gründliches (wenn auch bitteres) Verständnis der Bürokratie von Spire verschafft. Guensy kennt außerdem Adolise Vern, die Unter-Unterstaatssekretärin, die den Räumungsbescheid abgezeichnet hat, als ehemalige Schulkameradin. Die beiden trafen sich früher bei einem Drink, bis Guensy zur gesellschaftlichen Belastung wurde. Auf Nachfrage erzählt Guensy gern Schmutziges über Adolise.","**Was wünscht sich die Person?**","Guensy ist erschöpft und voller Verzweiflung bei der Aussicht, schon wieder umziehen zu müssen, nicht zuletzt, weil es sich Guensy nicht leisten kann. Noch immer sehnt sich Guensy nach der Geborgenheit und Sicherheit des alten Lebens, ist aber auch den Nachbarn ans Herz gewachsen und fühlt sich verpflichtet, der Gemeinschaft, die beim Überleben geholfen hat, etwas zurückzugeben.","**Was verachtet die Person?**","Bürokratie und Autoritätspersonen. Guensy fiel wegen offener Insubordination in Ungnade, und die Jahre in Derelictus, in denen Guensy Grauen um Grauen miterlebte, haben das Misstrauen gegenüber Macht und denen, die sie innehaben, vertieft. Dennoch versteht Guensy den Nutzen von Bürokratie und Regierung und zögert deshalb, den Mund aufzumachen.",{"t":"h","x":"Vorgeschlagene Szenen","p":189,"lvl":4,"id":"vorgeschlagene-szenen-3"},{"t":"szenen","x":["Eine der Spielerfiguren erleidet eine Verletzung und geht zu Guensy, um Hilfe zu bekommen. Guensy stellt keine Fragen, überbrückt die Zeit aber mit der Frage, was die Gruppe von den Räumungen hält und ob sie weiß, wohin es als Nächstes geht. Guensy ist knapp, aber effizient und kann sogar Schmerzmittel (oder Schnaps) anbieten, wenn der Patient sie will.","Die Figuren hören im Mietshaus Glas zersplittern. Zwei Vertreter von Harmonious Properties haben sich Zutritt zu Guensys Praxis erzwungen, um eine „Inspektion“ durchzuführen. Wenn man sie gewähren lässt, werden die Vertreter den Laden auseinandernehmen und mit allen verbotenen medizinischen Vorräten abziehen.","Als die Figuren nach einem langen Tag heimkehren, finden sie ein Päckchen Abführmittel vor ihrer Tür und eine Notiz von Guensy, die sich für die Verzögerung entschuldigt, genug für ihre Pferde zu beschaffen. Die Figuren haben diese Bitte nie geäußert, und es gibt keine Pferde in Derelictus, doch die gelieferte Menge würde ausreichen, um eine große Gruppe von Menschen zu beeinträchtigen oder Chaos zu stiften.","Auf einem Marktplatz begegnen die Figuren Guensy. Guensy hat verzweifelt versucht, einen Teil der medizinischen Vorräte loszuschlagen, um sich den Umzug leisten zu können, wird nun aber von ein paar Wachen aufgehalten, weil ohne Genehmigung verkauft wird."]},{"t":"h","x":"Die Tanten","p":189,"lvl":3,"id":"die-tanten"},{"t":"h","x":"Roseline Occain und Nadia Fevri","p":189,"lvl":4,"id":"roseline-occain-und-nadia-fevri"},"**Was bieten sie der Gemeinschaft?**","Zusammen sind sie das Herz der Gemeinschaft: einfühlsam, neugierig, liebevoll und zutiefst großzügig. Ist jemand zu krank, um sich zu bewegen, ruft Roseline Guensy herbei (da Marguerite den Keller nie verlässt), während Nadia ihre geheime Kräuterbrühe bringt, die sie scheinbar immer parat hat. Auch wenn sie manchmal überwältigend sein können, kann sich niemand das Gebäude ohne sie vorstellen.","**Was hebt sie vom Rest der Gemeinschaft ab?**","Sie unterhalten ein weitläufiges Netz an Kontakten in Derelictus, viele davon Kunden oder Händler rund um ihren Straßenstand vor dem Schierlingsfruchtmarkt. Die meisten ihrer Kunden sind Einheimische, die Geschenke kaufen, oder Schmuggler, die Souvenirs abholen, aber sie sehen auch gelegentlich Touristen, die einen Schmuck kaufen wollen, um ihren Erfolg zu beweisen. Als gewiefte Geschäftsfrauen haben sie einen scharfen Blick für Menschen, ein gutes Gedächtnis und ein unkompliziertes Auftreten, das dazu einlädt, im Austausch gegen Ratschläge Vertrauliches preiszugeben.","**Was wünschen sie sich?**","Roseline macht sich Sorgen um ihren Sohn, der für sein Alter groß ist. Er ist ein Jahr zu jung, um für seine Dienstzeit geholt zu werden, aber wenn die Wachen ihn zu Gesicht bekommen, werden sie nicht zögern, ihn ohne Nachfrage zu schnappen und Roseline anschließend dafür zu bestrafen, dass sie ihn verborgen hat. Derzeit versucht sie, genug Geld zusammenzukratzen, um früher umzuziehen oder wenigstens die Wachen zu bestechen.","Nadia hat eine Krankheit, die Marguerites Zauberei braucht, um in Schach gehalten zu werden. Sie fürchtet, dass ihr niemand sonst helfen kann, wenn sie wegziehen muss. Sie ist verzweifelt auf der Suche nach einem Weg zu bleiben oder nach genug Geld, um das gerüchteweise existierende Heilmittel zu kaufen. Beide Frauen wollen trotz ihrer Probleme ihr Zuhause und ihre Gemeinschaft verteidigen, wenn sie können; vielleicht verstehen sie mehr als alle anderen, wie viel auf dem Spiel steht.","**Was verachten sie?**","Die Herzlosen, die Illoyalen, die Unzuverlässigen. An einem so verarmten Ort wie Derelictus verachten Roseline und Nadia Nachbarn, die Dinge tun, die allen anderen in der Gemeinschaft schaden, denn nur wenige sind so wohlhabend, dass sie nicht in dem einen oder anderen auf andere angewiesen wären.",{"t":"img","src":"erw/str/str_190_01","w":1100,"h":1424,"p":190},{"t":"schwarz","b":["Die Kinderbanden von Derelictus singen im Singsang Riten, um ihre Göttinnen um Macht und Beistand anzuflehen."],"p":190},"Sie haben ein langes Gedächtnis und scheuen sich (wie die meisten Tanten) nicht, ihr Netz zu nutzen, um andere zu warnen, sobald sie von einem Vergehen überzeugt sind.",{"t":"h","x":"Fallout","p":191,"lvl":4,"id":"fallout-2"},{"t":"hw","x":[{"k":"MISSTRAUT","x":"[Leicht, Schatten/Ruf] Die Menschen in Derelictus wissen nicht unbedingt, was ihr getan habt (Entscheidung der Spielleitung, ob die Einzelheiten der Gemeinschaft schaden oder nützen würden), aber sie wissen, dass man euch nicht trauen kann. Händler aus Derelictus verkaufen euch zu Touristenpreisen und lassen nicht mit sich handeln, während eure Nachbarn Abstand halten und darauf warten, dass ihr einen Fehler macht – es sei denn, ihr macht es wieder gut.","p":191}]},{"t":"h","x":"Vorgeschlagene Szenen","p":191,"lvl":4,"id":"vorgeschlagene-szenen-4"},{"t":"szenen","x":["Roseline lädt die Spielerfiguren zu einem letzten Plausch bei Abendessen oder Drinks mit ihr und Nadia ein. Sie haben bei allen im Gebäude nachgesehen und geben gern Klatsch weiter, wenn sie den Figuren vertrauen (oder versuchen, die wahren Absichten und Loyalitäten der Figuren herauszubekommen, wenn nicht).","Die Figuren kommen an ihrem Stand in Derelictus vorbei, als Nadia sie heranruft, um sich ihre Waren anzusehen, und beteuert, sie habe etwas Besonderes. Während Roseline für Ablenkung sorgt, führt Nadia die Gruppe in den hinteren Teil des Standes, um etwas Gefälschtes anzubieten, das die Gruppe braucht (ob sie danach gefragt hat oder nicht), sowie ein paar Snacks.","Roseline und Nadia verhandeln mit Bezo, einem Leutnant der Kehrer [[Sweepers]] (der Bande, die diesen Teil von Derelictus derzeit kontrolliert), über Gegenwehr gegen die Wachen. Bezo beharrt darauf, die Tanten müssten verrückt sein, wenn sie glauben, eine örtliche Bande könne es mit ihnen aufnehmen."]},{"t":"h","x":"Der Ehemalige Masked","p":191,"lvl":3,"id":"der-ehemalige-masked"},{"t":"h","x":"Amondieu Loukes","p":191,"lvl":4,"id":"amondieu-loukes"},"**Was bietet er der Gemeinschaft?**","Indem er sich entschied, nach seiner Dienstzeit in einem Palast in Amaranth nach Derelictus heimzukehren, bietet er denen, die noch hier leben, eine Art Bestätigung (auch wenn ihm dieser Gedanke unangenehm ist). Was er tatsächlich anzubieten hat, ist das Verständnis eines Dieners für die Aelfir, den Charme eines bevorzugten Gladiators und Finesse mit einer Vielzahl von Waffen – nicht, dass er seit seiner Rückkehr auch nur eine berührt hätte.","**Was hebt ihn vom Rest der Gemeinschaft ab?**","Amondieu fühlt sich schuldig, Faizels Aufmerksamkeit auf dieses Gebäude gelenkt zu haben, als er während seiner Dienstzeit über seine Kindheit sprach und beschloss, nach seinem Dienst zurückzukehren. Das hat er niemandem gegenüber erwähnt. Schlimmer noch: Amondieu vermutet, dass sein früherer Herr glaubt, hilfreich zu sein, und keine Kritik annehmen wird.","**Was wünscht er sich?**","Er hat einen Freund in Red Row, bei dem er unbedingt einziehen möchte, macht sich aber Sorgen um seine Mutter. Er hat die Schrecken der Arenen nicht überlebt, um sie jetzt im Stich zu lassen, und er fühlt sich schuldig, dass seine Abwesenheit – wenn auch erzwungen – zu ihrem Verfall beigetragen hat. Er will sie wieder gesund sehen oder zumindest in guten Verhältnissen lebend.","**Was verachtet er?**","Menschen, die ohne Ehre handeln oder sein Volk als entbehrlich behandeln – vor allem seinen früheren Herrn. Er hat zugesehen, wie die Aelfir unzählige arme Drow zur Unterhaltung in ihre privaten Arenen und Duellplätze warfen, und hat sein gerüttelt Maß von ihnen getötet, um zu überleben. Die Erfahrung hat ihm Albträume beschert. Im Wachzustand ist er unerbittlich entschlossen, so etwas nie wieder zu dulden.",{"t":"h","x":"Vorgeschlagene Szenen","p":191,"lvl":4,"id":"vorgeschlagene-szenen-5"},{"t":"szenen","x":["Obwohl er seit dem Ende seines Dienstes keine Waffe mehr in die Hand genommen hat, trainiert Amondieu weiterhin täglich in der Nachbarschaft, um in Kampfform zu bleiben. Über seine vergangene Dienstzeit und seine heutigen Motive kursieren Gerüchte, doch nach der Menge an Bewunderern zu urteilen, die sich stets versammelt, hat niemand Lust zu bohren. Mindestens einer alten Dame muss danach immer über die Straße geholfen werden.","Amondieu packt seine alten Masken ein, als die Spielerfiguren vorbeikommen, um ihn oder Mama Loukes zu besuchen, die nicht da ist. Auf Nachfrage gibt er zu, die Masken aus seiner Dienstzeit behalten zu haben, obwohl er nie vorhatte, sie wieder zu tragen. Sie könnten nützlich sein, wenn die Figuren ihn überzeugen können, sich davon zu trennen, aber das wird nicht leicht.","Bezo, ein Leutnant der Kehrer (der Bande, die diesen Teil von Derelictus derzeit kontrolliert), versucht, Amondieu anzuwerben. Sie haben irgendwie von seiner Gladiatoren-Vergangenheit erfahren und wollen unbedingt einen gut ausgebildeten Schläger gewinnen. Amondieu fällt es schwer, seine Wut zu zügeln, und es ist nur eine Frage der Zeit, bis jemand verletzt wird.","Misstrauisch gegenüber den Figuren, folgt Amondieu ihnen, um herauszufinden, was sie wirklich vorhaben. Er fürchtet, dass ihr Tun ihren Nachbarn schaden wird – oder, schlimmer, ganz Derelictus."]},{"t":"h","x":"Die Horterin","p":192,"lvl":3,"id":"die-horterin"},{"t":"h","x":"Mama Loukes","p":192,"lvl":4,"id":"mama-loukes"},"**Was bietet sie der Gemeinschaft?**","Sie ist Amondieus Mutter und eine Hortende mit mindestens drei Katzen. Seit eine Verletzung sie vor Jahren in den Frühruhestand zwang, beobachtet sie jeden Tag die Kinder auf den Dächern von ihrem Sitzplatz auf einem umgestülpten Eimer aus, einen Stock in der Hand, der heimlich auch als Armbrust dient. Die Kinder erzählen Geschichten von einem finsteren Handel mit King Teeth höchstpersönlich, über den sie stets lacht. Was auch immer die Wahrheit ist: Seit sie damit begonnen hat, hat kein Ghul mehr ein Kind geholt.","**Was hebt sie vom Rest der Gemeinschaft ab?**","In den letzten Jahren hat sie eine Besessenheit entwickelt, Schrott in verblüffend nützliche Gegenstände umzuwandeln. In der Gemeinschaft ist sie für ihr Spielzeug und ihre einfachen Gerätschaften bekannt, doch zwischen den Aufträgen fordert sie sich mit immer komplexeren Projekten heraus. Unbekannt für alle außer Marguerite hat sie den Kontakt zu einem früheren Nachbarn gehalten, der unter King Teeth zum Ghul wurde. Er hält die anderen Ghule tagsüber vom Dach des Gebäudes fern, damit die Kinder spielen können.","**Was wünscht sie sich?**","Sie will in ihrer Wohnung bleiben, beim Geist ihres Mannes, der starb, während Amondieu fort war, aber in der Wohnung blieb, um ihr Gesellschaft zu leisten. (Amondieu sieht keine Geister und glaubt nicht an sie; das ist eine endlose Quelle der Reibung zwischen ihnen, denn sie wirft Amondieu vor, zum Aelfir geworden zu sein.) Da der Geist ihres Mannes an die Wohnung gebunden ist, weigert sie sich, an einen Umzug auch nur zu denken oder den Räumungsbescheid zur Kenntnis zu nehmen.","**Was verachtet sie?**","Aelfir und Aelfir-Sympathisanten. In ihrer Jugend war sie eine Drow-Traditionalistin mit rebellischer Ader, wenngleich sie nie so weit ging, dem Ministerium beizutreten. Die Zeit hat ihr Temperament gemildert, auch wenn sie sie nicht davon abhält, hinter verschlossenen Türen zu schimpfen oder harmlose Streiche zu spielen, etwa funktionierende Türscharniere gegen quietschende auszutauschen, um jene zu ärgern, denen sie misstraut.",{"t":"h","x":"Vorgeschlagene Szenen","p":192,"lvl":4,"id":"vorgeschlagene-szenen-6"},{"t":"szenen","x":["Mama Loukes sitzt an ihrem gewohnten Platz auf dem Dach und sieht den Kindern beim Spielen zu. Sie trommelt mit den Fingern auf ihren Stock und hat ein Ohr der Straße unten zugewandt, wo zwei Angestellte von Harmonious Properties besprechen, wie man das Mietshaus am besten abreißt.","Beim Durchwühlen eines Schrotthaufens in Red Row wird Mama Loukes von einer Wachpatrouille gepackt und zurück nach Derelictus geschleift. Sie protestiert laut, sie habe nichts Unrechtes getan, aber keiner der anderen Bewohner von Red Row schenkt dem Beachtung. Einer der Wachen schlägt ihr mit dem Handrücken ins Gesicht und sagt, Ratten sollten ihren Platz kennen.","Als die Spielerfiguren Mama Loukes oder Amondieu besuchen kommen, ist Amondieu nicht da, aber Mama Loukes packt hektisch eine Kiste aus und stellt Gegenstände zurück ins Regal. Der Raum ist voller weiterer gepackter Kisten, die aussehen, als wären sie schon mindestens einmal neu zugeklebt worden."]},{"t":"h","x":"Drogendealerinnen","p":192,"lvl":3,"id":"drogendealerinnen"},{"t":"h","x":"Zette und Selavi","p":192,"lvl":4,"id":"zette-und-selavi"},"**Was bieten sie der Gemeinschaft?**","Zette und Selavi bleiben meist für sich, haben aber eine feste Abmachung mit Guensy: Sie beschaffen Vorräte im Tausch gegen diskrete medizinische Hilfe, wann immer sie sie brauchen. Sie nehmen bekanntermaßen hin und wieder Schwarzmarktbestellungen anderer Bewohner an – typischerweise Drow-Delikatessen aus den Heimatnationen, etwa Gläser mit Sternengelee (ein rauchfarbenes Dessert, das von leuchtenden Höhlenalgen funkelt) oder gewürzte Leichenfrucht-Teemischungen.","**Was hebt sie vom Rest der Gemeinschaft ab?**","Sie fürchten, dass das Mietshaus als Teil einer verdeckten Drogenrazzia ins Visier genommen wurde: Ihr Schlafzimmer ist teilweise in ein kleines Labor zur Herstellung von Malak umgebaut worden.","Zettes Verbindungen zum Schwarzmarkt reichen tief. Bevor sie sesshaft wurde, um ihr eigenes Geschäft zu führen, verbrachte sie einige Jahre als Leichenfrucht-Schmugglerin auf den unterirdischen Routen. Selavi arbeitet derweil als Teilzeitkellnerin in der Zivilisation und versteht sich gut mit den Stammgästen, darunter eine Handvoll Journalisten, die sie wegen unbekannter (und oft eingebildeter) Schrecken in Derelictus bedrängen, um sie zu sensationalisieren.","**Was wünschen sie sich?**","Beide sind nach dem Recht von Spire technisch gesehen Kriminelle, doch Selavi ist stärker gefährdet, weil sie noch immer gesucht wird, da sie sich ihrer Dienstzeit entzogen hat. Während Selavi damit beschäftigt ist, Notfallpläne für ihre Notfallpläne zu schmieden, ist Zette bereit, alles zu tun, damit ihre Geliebte am Leben bleibt.","**Was verachten sie?**","Zette hasst es, hilflos zu sein oder warten zu müssen. Sie ist unter den Bewohnern diejenige, die am ehesten etwas Unbesonnenes tut, was gefährlich ist, weil sie Selavi über alle anderen in der Gemeinschaft stellt – sie selbst eingeschlossen.","Selavi ist zugleich amüsiert und verächtlich gegenüber den Außenstehenden, die in letzter Zeit vorbeikommen. Besonders verachtet sie die Touristen, die sich nach Derelictus wagen, um zu gaffen, und hat sich mehr als einmal mit den Tanten gestritten, warum sie an diese Leute verkaufen. (Die Tanten halten sie für Narren, die man leicht von ihrem Geld trennt.)",{"t":"h","x":"Vorgeschlagene Szenen","p":193,"lvl":4,"id":"vorgeschlagene-szenen-7"},{"t":"szenen","x":["Die Spielerfiguren sind in der Zivilisation, als ein betrunkener Drow nach Selavi greift, während seine Begleiter lachen. Als sie schreit und versucht, sich loszureißen, sagt der Drow, sie solle froh sein, dass die Wachen außer Dienst heute Abend sie ausgesucht haben. Es ist unklar, ob sie tatsächlich Wachen sind, aber sie sind kampfstark gebaut. Sie sieht sich nach Beistand um, doch keiner der anderen Gäste der Bar sieht ihr in die Augen. Die Türsteher, die sonst gern mitten ins Getümmel springen, zögern auf ihren Posten.","Vertreter von Harmonious Properties klopfen laut an ihre Tür, um die Wohnung zu inspizieren, doch Zette weigert sich, sie hereinzulassen, und schiebt Möbel vor die Tür. Selavi versucht, ihren Malak-Aufbau so schnell sie kann abzubauen.","Während Selavi unterwegs ist, lädt Zette die Spielerfiguren zu sich ein, um ihnen etwas von ihrem überschüssigen Malak anzubieten, das sie vor dem Umzug loswerden müssen. Ihr ist es natürlich ziemlich egal, ob die Figuren es selbst konsumieren, aber sie lässt beiläufig fallen, dass der Besitz mehr als genug ist, um jemandes Leben zu ruinieren, falls diese Information nützlich ist. (Für zusätzliche Spannung führen Wachen von Harmonious Properties eine Razzia in ihrer Wohnung durch, während die Spielerfiguren anwesend sind, und es liegt an ihnen, ihr zu helfen, die Beweise loszuwerden.)"]},{"t":"h","x":"Das Ende der Geschichte","p":193,"lvl":2,"id":"das-ende-der-geschichte"},"Wenn die Spielenden die Räumungen geschehen lassen, werden die Wachen in einer Woche mit voller Macht über das Mietshaus herfallen. Sie werden jeden hinauswerfen, den sie drinnen finden, und alles mitnehmen, was nach etwas Wertvollem aussieht, um ihre Zeit zu entschädigen.","Einige Bewohner werden kämpfend untergehen, die übrigen werden sich überallhin verstreuen, wo man sie aufnimmt: zu Freunden und Familie, wenn sie Glück haben, sonst auf die Straße, zu King Teeth, zur Kirche der Absolution oder zu einer der Banden. Viele werden die einjährige Wartezeit auf die Teilnahme an der Wohnungslotterie für das neue Gebäude nicht überleben.","Harmonious Properties wird erfolgreich an den neuen Bewohnern experimentieren, die bald den Ruf erlangen, seltsam und distanziert zu sein, während sie nach und nach der Vyskant-Krankheit verfallen. Unbekümmert um die Gefahr wird Faizel dieses Projekt nutzen, um für ein Amt zu kandidieren, mit dem Ziel, sein Projekt (und, unwissentlich, die Reichweite des Herold-Konzerns) auf den Rest von Derelictus auszudehnen.","Um diesem Schicksal zu entgehen, müssen die Spielenden sich mit Faizel, den Wachen oder beiden auseinandersetzen. Selbst wenn Harmonious Properties sich aus dem Projekt zurückzieht, müssen Faizel und die Wachen weiterhin bewältigt werden.","Es ist möglich, das Spiel früher zu beenden, wenn Faizel den Räumungsbefehl zurücknimmt. In diesem Fall bleibt das Gebäude baufällig, und zumindest die Nachbarn werden den Eigentümerwechsel bemerken. Sie werden wissen wollen, was die Figuren als Nächstes vorhaben, ob sie noch umziehen müssen und was mit dem Gebäude selbst geschehen soll. Wie das abläuft, hängt vom Verhältnis der Figuren zu ihren Nachbarn ab, aber die Schlussszene könnte ein feierlicher Kuchen sein, eine angespannte Hausversammlung oder sogar ein Gespräch mit den Tanten darüber, wie man die Nachricht diskret verbreitet.","Wenn Faizel den Befehl nicht zurücknimmt, leitet die Ankunft der Wachen die letzte Szene dieser Geschichte ein.",{"t":"h","x":"Faizel Schnee-Fällt-auf- Glut","p":193,"lvl":3,"id":"faizel-schnee-faellt-auf-glut"},{"t":"h","x":"Voraussetzungen","p":193,"lvl":4,"id":"voraussetzungen"},"**Wissen:** Faizel ist überzeugt, es besser zu wissen. Er glaubt, das Problem zu verstehen, die Lage mit ausreichender Gründlichkeit erwogen und die praktischste Lösung gefunden zu haben. Um eine Chance zu haben, zu ihm durchzudringen, müssen die Spielenden über den tatsächlichen Zustand des Gebäudes informiert sein. Andernfalls wird Faizel diese Informationen gegen sie verwenden, einschließlich der allgemeinen Baufälligkeit des Gebäudes, der Schäden im Fundament, der hereinsickernden okkulten Energie und des Plans, subventionierten Wohnraum und Gratisessen anzubieten. Um sich einen Vorteil zu verschaffen, können die Spielenden Informationen anbieten, die er nicht kennt – etwa die Verbindung von Harmonious Properties zum Herold-Konzern, ihre wahren Absichten mit dem Gebäude oder den aggressiven Plan der Wachen für die Räumungen.","**Zugang:** Außerhalb seines geplanten Besuchs Zugang zu Faizel zu bekommen wird schwierig, aber nicht unmöglich. Er wird in der Woche mindestens eine Feier ausrichten, und wie es sich gehört, werden alle maskiert sein. Zugang zu ihm zu bekommen, wenn er das Gebäude besucht, wird etwas leichter sein, aber sein Besuch wird kurz sein und streng von Vertretern von Harmonious Properties gesteuert.",{"t":"h","x":"Strategie","p":194,"lvl":4,"id":"strategie"},"**Überzeugung:** Faizel ist nicht unvernünftig und kann dazu gebracht werden, seine Pläne anzupassen (besonders, wenn er denkt, es sei seine Idee!). Allerdings neigt er dazu, schlecht von den Bewohnern zu denken. Die Figuren können dafür argumentieren, seine Ambitionen in hilfreichere Bahnen zu lenken, doch dazu müssen sie alles über die Lage wissen. Wie bei den meisten Aelfir sind Appelle ans Herz nicht besonders nützlich. Für einen Geschäftsmann wie Faizel sind Geld und Vernunft (oder zumindest ein Appell an sein Vernunftgefühl) wohl wirksamer. Amondieu kennt seine Persönlichkeit, seinen Geschmack und seine Schwächen, falls die Spielenden das Beste daraus machen wollen.","**Erpressung:** Neben der Drohung, Faizels bekannte Schwächen offenzulegen, ist sein Mitgefühl für die Lage der Drow für einen Aelfir seines Ranges unschicklich – und damit eine Belastung für seine politischen Ambitionen, sollte es öffentlich bekannt werden. Sein Ruf ist noch unbekannt. Die Figuren können damit drohen, ihn zu beschädigen, indem sie einem Journalisten Informationen über seine Ansichten, vergangene Skandale, die Wahrheit hinter dem Gebäude und/oder die wahren Pläne von Harmonious Properties für das Gebäude und seine Bewohner zukommen lassen.","**Sabotage:** Die Figuren können (selbst oder über einen Journalisten) beschafftes Erpressungsmaterial enthüllen, um die Glaubwürdigkeit des Projekts zu beschädigen und alle Beteiligten stärker ins Licht der Öffentlichkeit zu rücken. Sie können außerdem das Genehmigungsverfahren stören, es für Faizel finanziell unbequem machen, ein neues Vorhaben zu beginnen, oder Faizel etwas Belastendes unterschieben und einen anonymen Hinweis verfassen.","**Entschädigung:** Die Spielenden können beschließen, genug Geld aufzutreiben, um Faizel einen Anteil am Gebäude (oder das ganze) abzukaufen, wenn sie wissen, wie viel das Gebäude ursprünglich wert war, und ihn überzeugen können, dass sie die Richtigen sind, um ihr Zuhause zu verwalten.","**Attentat:** Faizel zu töten stoppt das Projekt auf unbestimmte Zeit, vorausgesetzt, die Spielenden überleben sein persönliches Gefolge. Sie werden wahrscheinlich mehr Aufmerksamkeit auf sich ziehen, als ihnen lieb ist. Wenn der Auftrag auf sie zurückverfolgt werden kann, könnte sie jemand anzeigen, oder das Ministerium könnte entscheiden, dass sie ein zu großes Risiko sind, um sie zu behalten. Die Stadtwache wird auf jeden Fall herumschnüffeln und muss irgendwie bewältigt werden.",{"t":"h","x":"Schluss","p":194,"lvl":4,"id":"schluss"},"Faizel wird die Wachen zurückrufen oder nicht, je nach Erfolg der Handlungen der Figuren. Ihn zu überzeugen, seine Pläne zu ändern, ist keine leichte Aufgabe, und ihn zu überzeugen, das Projekt ganz aufzugeben, wird bestenfalls schwierig. Geschieht dies aber doch, wird er Berge versetzen.","Ruft er die Wachen nicht zurück, werden sie versuchen, die Bewohner zu räumen. Details zu diesem Konflikt findest du im Abschnitt „Wachen“ unten.","Wird Faizel ermordet, könnten die Wachen dennoch zum Mietshaus kommen, um seinen Tod zu untersuchen und die Bewohner zu verhören. In diesem Fall können die Figuren nach der Flucht vom Tatort versuchen, sich durch ein hartes Verhör zu bluffen oder unterzutauchen (mit dem Risiko eines Schlags für ihren Ruf und ihr unbewachtes Zuhause). So oder so könnte ihre Tarnung von verängstigten oder grollenden Nachbarn auffliegen. Immerhin leben sie vorerst.",{"t":"h","x":"Wachen","p":194,"lvl":3,"id":"wachen"},{"t":"h","x":"Strategie","p":194,"lvl":4,"id":"strategie-2"},"Unten stehen einige gängige Optionen, wie man mit den Wachen umgeht. Sie können nützlich sein, wenn deine Spielenden eine Richtung brauchen, aber gib ihnen Raum, eigene Lösungen zu finden.","Diese besondere Wachgruppe ist in Vorloren Standard stationiert: dem schlechtesten Posten im ganzen Spire. Einige haben vielleicht gerechte und edle Absichten, doch sie sind mit verbitterten Außenseitern auf der Suche nach Erlösung und blutdürstigen Sadisten in einen Topf geworfen. Leider für die Figuren melden sich die beiden letzteren Gruppen eher freiwillig für eine Aufgabe wie diese.","**Die Nachbarn mobilisieren:** Die Figuren können ihre Nachbarn mobilisieren, um die Wachen zu vertreiben, aber die meisten werden zögern: Einige haben gute Gründe, unnötige Aufmerksamkeit zu meiden, und die meisten haben begrenzte Kampffertigkeiten. Niemand will sterben, aber sie sind wütend und frustriert, was die Figuren zu ihrem Vorteil lenken können. Wirkt der Plan jedoch zu leichtsinnig oder gefährdet er wahrscheinlich ihr Leben, könnten die Nachbarn ihn ablehnen. Sie könnten sogar Parallelen zwischen dem Plan und dem Ruf des Ministeriums für Pyrrhussiege ziehen und sich stattdessen gegen die Spielenden wenden.","**Die Gemeinschaft organisieren:** Die Figuren können sich an andere Fraktionen, Gemeinschaften und Einzelne um Hilfe wenden, aber jeder hat seinen Preis. Es ist riskant, gegen die Wachen vorzugehen, selbst indirekt. Allerdings: Werden die Wachen, bis an die Zähne bewaffnet, sich mit einer Routineräumung zufriedengeben, oder wird der Distrikt ein zu verlockender Prügelknabe für ihren Frust über Red Row sein? Niemand ist besonders scharf darauf, es herauszufinden.","Einige Gruppen, etwa die Händler auf dem Schierlingsfruchtmarkt, wollen die Wachen um jeden Preis aus ihrem Teil von Derelictus heraushalten. Andere, etwa die Gäste in der Zivilisation, würden sich lieber nicht die Hände schmutzig machen, könnten aber helfen, die Lage anderswo in Spire bekannt zu machen, sogar Spenden zu sammeln. Die örtlichen Banden sind immer auf Streit aus und scharf darauf, ihr Revier zu verteidigen, während die Ghule in Grist deftigere Kost als den durchschnittlichen Bürger von Derelictus zu schätzen wissen. Die Figuren können sogar die Kirche der Absolution überreden, einige Schutzzauber zu errichten oder zu helfen. Es ist schwerer, Unterstützung von jenseits des Distrikts zu sammeln, aber nichts ist unmöglich.","**Die Wachen sabotieren:** Die Figuren können im Voraus Komplikationen einführen, um die Wirksamkeit der Wachen zu verringern. Verdorbenes Essen oder Trinken, ein kleiner Skandal, die Sabotage oder der Diebstahl von Ausrüstung und Vorräten, eine unruhige Woche Schlaf oder gute altmodische Bestechung sind allesamt Wege, die Wachen zu schwächen. Sie könnten dadurch gereizter sein, aber auch weniger effektiv. Ernsthafte Komplikationen wie Mord oder Brandstiftung sollten dramatischere Konsequenzen nach sich ziehen – etwa eine verstärkte Wachpräsenz oder eine Ausgangssperre. Sie werden sicherlich abgelenkt sein, aber selbst wenn die Figuren nicht erwischt werden, wird jemand die hässlichen Folgen tragen müssen.","Die Figuren können außerdem Hindernisse für den Räumungstag vorbereiten, etwa ein Netz aus Straßensperren und Barrikaden, einen ungünstig geführten Umzug, ein Straßenfest, ein umherstreifendes Ghulrudel oder Ablenkungen anderswo. Denk daran, dass die Wachen den Großteil von Red Row durchqueren müssen, ehe sie nach Derelictus hinabsteigen, und beides ist in Uniform nicht besonders sicher zu durchqueren. Sie werden wütend und in Abwehrhaltung sein.",{"t":"h","x":"Schluss","p":195,"lvl":4,"id":"schluss-2"},"Die Figuren werden es schwer haben, die Wachen zum Abzug zu überreden, aber es könnte möglich sein, wenn die Spielenden ihre Interessen ansprechen können. Wahrscheinlicher ist, dass die Figuren ihre Mittel und Unterstützung bündeln, um die Wachen zu vertreiben.","Auch die Wachen werden ihre eigenen Vorbereitungen getroffen haben: Sie kommen bewaffnet, gerüstet und aggressiv. Sie werden versuchen, auf den Hauptwegen zu bleiben, um nicht überrascht zu werden, und sie kommen in Stärke und Formation, damit sie nicht leicht überwältigt werden können. Dennoch liebt niemand den Job so sehr, dass er sein Leben dafür gäbe. Wenn es schlecht aussieht, werden sie sich zurückziehen.",{"t":"gegner","id":"erw-str-stadtwachen-raeumungstrupp"},{"t":"h","x":"HANDOUT: RÄUMUNGSBESCHEID (Vorder- und Rückseite)","p":196,"lvl":2,"id":"handout-raeumungsbescheid-vorder-und-rueckseite"},{"t":"h","x":"Bekanntmachung","p":196,"lvl":1,"id":"bekanntmachung"},"Stadt Spire","Amt für Wohnungswesen","Gemäß Abschnitt 48.17 der Städtischen Wohnungsordnung der Stadt Spire wird das Grundstück Boundary Street 228 im Distrikt Derelictus hiermit für ungeeignet oder unsicher für Wohnzwecke erklärt.","Es ist jeder Person untersagt, dieses Gebäude zu nutzen oder zu bewohnen, ausgenommen Personen, die vom Vermieter und vom Amt für Wohnungswesen zum Abriss des Gebäudes ermächtigt sind: Angestellte von Harmonious Properties.","Der Vermieter verlangt, dass Sie die Räumlichkeiten innerhalb von 7 Tagen nach diesem Aushang am 3. Ernte im Jahr der Vielen Omen räumen.","Vermieter:","Faizel Schnee-fällt-auf-Glut","Genehmigt von:\tAdolise Vern","Unter-Unterstaatssekretärin, Amt für Wohnungswesen","Personen, die gegen diese Bekanntmachung verstoßen, werden mit der vollen Härte des Gesetzes verfolgt.",{"t":"img","src":"erw/str/str_197_01","w":882,"h":1247,"p":197},"Etwas Initiative","zeigen.","-S",{"t":"img","src":"erw/str/str_198_01","w":1100,"h":1424,"p":198},{"t":"schwarz","b":["Die Bürger von La Grotte de Corde sichern sich mit ihren pittoresken ländlichen Bräuchen eine weitere ergiebige Ernte."],"p":198}],"abenteuer":true};
